design.css:
/* Reel — the animepahe look. Measured from the live site (docs/theme-references/animepahe.md). */

/* ---------- Header: a 47 px black bar with the content in an 1100 px column ---------- */
[data-slot="nav.top"] {
  background: #000;
  border-bottom: 0;
  padding-left: max(12px, calc((100vw - 1100px) / 2));
  padding-right: max(12px, calc((100vw - 1100px) / 2));
  gap: 0;
}
/* The wordmark stands alone, as the site's does: drop the logo mark's link box. */
[data-slot="nav.top"] a[data-slot="brand"]:not(:has([data-part="brand.text"])) { display: none; }
[data-slot="nav.top"] [data-part="brand.text"] {
  font-family: var(--ui-font);
  font-size: 26px;
  font-weight: 400;
  letter-spacing: -0.5px;
  color: #fff;
  margin-right: 16px;
}
[data-part="brand.char"]:nth-child(n + 4) { color: #d5015b; }
[data-slot="nav.top"] [data-part="nav.item"] {
  height: 37px;
  padding: 8px 15px;
  border-radius: 0;
  background: rgba(0, 0, 0, 0.4);
  color: #fff;
  font-size: 14px;
  font-weight: 400;
  text-transform: lowercase;
}
[data-slot="nav.top"] [data-part="nav.item"][data-active] { color: #fff; background: rgba(0, 0, 0, 0.4); }
[data-slot="nav.top"] [data-part="nav.item"]:hover { color: #d5015b; background: rgba(0, 0, 0, 0.4); }
[data-slot="nav.top"] :has(> [data-part="search.field"]) { width: 225px; }
[data-slot="nav.top"] [data-part="search.field"] {
  height: 36px;
  border: 0;
  border-radius: 0;
  background: #e7edf3;
  color: #667d99;
  font-size: 13px;
}

/* ---------- Home: "Latest Releases" in a centred 1100 px column ---------- */
[data-slot="home"] { max-width: 1100px; margin-left: auto; margin-right: auto; padding-top: 24px; }
[data-slot="block.latest-episodes"] { padding-left: 0; padding-right: 0; }
[data-slot="block.latest-episodes"] [data-part="block.title"] {
  font-size: 32px;
  font-weight: 300;
  color: #eee;
  margin: 0 0 16px;
}
[data-slot="block.latest-episodes"] :has(> [data-part="block.item"]) { gap: 10px; }
[data-slot="block.latest-episodes"] [data-part="block.item"] > button,
[data-slot="block.latest-episodes"] [data-part="episode.still"] { border-radius: 0; }
[data-slot="block.latest-episodes"] [data-part="card.title"] { font-size: 12.8px; font-weight: 500; }
[data-slot="block.latest-episodes"] [data-part="episode.number"] { font-size: 19.2px; font-weight: 600; }

/* Pager: « ‹ n › » — only the current page number shows. */
[data-part="pagination"] { gap: 0; }
[data-part="pagination"] > span { display: none; }
[data-part="pagination"] [data-part="page-number"]:not([data-active]) { display: none; }
[data-part="pagination"] button {
  height: 38px;
  min-width: 35px;
  padding: 8px 12px;
  border: 1px solid #000;
  border-radius: 0;
  background: #111;
  color: #a20145;
  font-size: 16px;
  font-weight: 400;
}
[data-part="pagination"] [data-part="page-number"][data-active] { background: #d5015b; color: #fff; }

/* ---------- Series page: a centred 1100 px column, synopsis beside a facts column ---------- */
[data-slot="detail"][data-variant="desktop"] > div:has([data-part="detail.title"]) {
  max-width: 1100px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 0;
  padding-right: 0;
}
[data-slot="detail"][data-variant="desktop"] div:has(> [data-part="detail.title"]) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 250px;
  column-gap: 30px;
  align-items: start;
}
[data-slot="detail"][data-variant="desktop"] div:has(> [data-part="detail.title"]) > * { grid-column: 1; }
[data-slot="detail"] [data-part="detail.title"] {
  grid-column: 1 / -1 !important;
  grid-row: 1;
  margin-bottom: 0;
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 500;
  color: #fff;
}
[data-slot="detail"] [data-part="detail.alt-title"] {
  grid-column: 1 / -1 !important;
  grid-row: 2;
  margin-bottom: 12px;
  font-size: 17.6px;
  font-weight: 600;
  color: #fff;
}
[data-slot="detail"][data-variant="desktop"] [data-part="detail.facts"] { grid-column: 2 !important; grid-row: 3 / span 4; margin: 0; }
[data-slot="detail"] [data-part="detail.synopsis"] { font-size: 16px; line-height: 24px; color: #eee; }
[data-slot="detail"] [data-part="detail.poster"] { border-radius: 0; }
[data-part="detail.facts"][data-variant="table"] { display: block; font-size: 12px; line-height: 18px; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact"] { display: block; margin-bottom: 3px; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.label"] { display: inline; font-weight: 700; color: #eee; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.label"]::after { content: ":"; }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.value"] { display: inline; margin-left: 4px; color: #eee; }
[data-part="detail.facts"] [data-part="fact.value"] a { color: #d5015b; }
[data-slot="detail"] [data-part="button"] { border-radius: 0; }
[data-slot="detail"] [data-part="tabs"] { gap: 0; }
[data-slot="detail"] [data-part="tab"] { width: 180px; height: 50px; justify-content: center; text-align: center; font-size: 16px; font-weight: 400; color: #f1f1f1; border-radius: 0; }
[data-slot="detail.episodes"] [data-part="episode"],
[data-slot="detail.episodes"] [data-part="episode.still"] { border-radius: 0; }
[data-part="episode.number"] svg { color: #28a745; }
[data-slot="detail"] [data-part="tab"][data-active] { color: #fff; }
[data-slot="detail"] [data-part="tab"][data-active] > span { height: 2px; border-radius: 0; background: #d5015b; }
[data-slot="detail"] [data-part="detail.actions"] { gap: 6px; }
[data-slot="detail"] [data-part="detail.actions"] > * { height: 36px; min-height: 36px; font-size: 14px; }
[data-slot="detail"] [data-part="detail.actions"] [data-part="button"] { padding-left: 14px; padding-right: 14px; }
[data-slot="detail.episodes"] [data-part="badge"] { display: none; }
[data-slot="detail.episodes"] [data-part="episode"][data-variant="thumb"] { background: transparent; }
[data-slot="detail.episodes"] [data-part="episode"][data-variant="thumb"] [data-part="episode.number"] {
  top: auto;
  left: auto;
  right: 14px;
  bottom: 12px;
  padding: 0;
  background: none;
  font-size: 19.2px;
  font-weight: 600;
  color: #fff;
  text-shadow: 0 1px 2px #000;
}
[data-slot="detail.episodes"] [data-part="episode.title"] { font-size: 12.8px; font-weight: 500; }
